package com.johnny.hotel.wallet;
import com.johnny.hotel.damage.*;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.inspection.*;import com.johnny.hotel.repair.*;import com.johnny.hotel.service.*;import com.johnny.hotel.task.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.security.access.AccessDeniedException;import java.math.*;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class RepairOrderDevelopmentTest extends FinancialDevelopmentFixture{
 @Autowired RepairOrderService repairs;@Autowired InspectionService inspections;@Autowired RoomTurnoverTaskService turnovers;@Autowired HotelTaskService tasks;@Autowired TodoService todos;@Autowired DamageAssessmentService damage;@Autowired Flyway flyway;
 @BeforeEach void financeActor(){long id=users.registerEmployee(employeeRequest("FINANCE")).getId();created.add(id);actors.put("FINANCE",id);jdbc.update("UPDATE sys_user SET status=1 WHERE id=?",id);jdbc.update("INSERT INTO sys_user_role(user_id,role_id) SELECT ?,id FROM sys_role WHERE role_code='FINANCE'",id);}
 InspectionRequests.Decide fail(){return InspectionRequests.Decide.builder().passed(false).failureReason(InspectionFailureReason.STRUCTURAL_DAMAGE).notes("Major structural pipe and wall damage").build();}InspectionRequests.Decide pass(){return InspectionRequests.Decide.builder().passed(true).build();}
 RepairOrder open(){long b=stay();pay(b,"300");clock.day(3);checkout(b);long turnover=jdbc.queryForObject("SELECT id FROM room_turnover_task WHERE stay_id=(SELECT id FROM stay WHERE booking_id=?)",Long.class,b);as("MANAGER");turnovers.complete(turnover,"clean");var inspection=inspections.room(room1).get(0);var failed=inspections.decide(inspection.getId(),fail());return repairs.list(room1,0,null,1,20).getItems().stream().filter(r->r.getTaskId().equals(failed.getFollowupTaskId())).findFirst().orElseThrow();}
 long todo(long task){return jdbc.queryForObject("SELECT id FROM todo WHERE task_id=? AND is_active=1",Long.class,task);}void claimAck(RepairOrder r){as("STAFF");tasks.claim(r.getTaskId());assertEquals(0,todos.get(todo(r.getTaskId())).getStatus());todos.acknowledge(todo(r.getTaskId()),"starting repair");}
 @Test void migrationUpgradesV23Identity(){flyway.validate();assertEquals(1,jdbc.queryForObject("SELECT success FROM flyway_schema_history WHERE version='29'",Integer.class));var r=open();assertEquals(3,RepairPriority.CRITICAL.getCode());assertEquals(0,r.getStatus());assertNotNull(r.getIssueDescription());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM room_repair_task WHERE inspection_id=?",Integer.class,r.getInspectionId()));}
 @Test void structuralFailureCreatesExactlyOneRepairAndTask(){var r=open();assertEquals(5,jdbc.queryForObject("SELECT task_type FROM hotel_task WHERE id=?",Integer.class,r.getTaskId()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM room_repair_task WHERE inspection_id=?",Integer.class,r.getInspectionId()));}
 @Test void claimKeepsTodoPendingAndAcknowledgeStartsRepair(){var r=open();as("STAFF");tasks.claim(r.getTaskId());assertEquals(0,todos.get(todo(r.getTaskId())).getStatus());assertEquals(0,repairs.get(r.getId()).getStatus());todos.acknowledge(todo(r.getTaskId()),null);assertEquals(1,todos.get(todo(r.getTaskId())).getStatus());assertEquals(1,repairs.get(r.getId()).getStatus());assertNotNull(repairs.get(r.getId()).getStartedTime());}
 @Test void genericCompletionCannotBypassRepair(){var r=open();claimAck(r);assertThrows(BusinessException.class,()->todos.complete(todo(r.getTaskId()),null));assertThrows(BusinessException.class,()->tasks.complete(r.getTaskId(),null));assertEquals(1,repairs.get(r.getId()).getStatus());}
 @Test void specializedCompletionClosesTaskTodoAndCreatesReinspection(){var r=open();claimAck(r);var done=repairs.complete(r.getId(),RepairRequests.Complete.builder().actualCost(new BigDecimal("875.25")).notes("Pipe and wall repaired").build(),false);assertEquals(2,done.getStatus());assertEquals(2,todos.get(todo(r.getTaskId())).getStatus());assertEquals(2,jdbc.queryForObject("SELECT status FROM hotel_task WHERE id=?",Integer.class,r.getTaskId()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM housekeeping_inspection WHERE repair_order_id=? AND status=0",Integer.class,r.getId()));}
 @Test void completionNeverReleasesAndPendingReinspectionBlocks(){var r=open();claimAck(r);repairs.complete(r.getId(),null,false);assertEquals(3,jdbc.queryForObject("SELECT status FROM room WHERE id=?",Integer.class,room1));assertThrows(BusinessException.class,()->rooms.setRoomAvailable(room1));var next=inspections.room(room1).stream().filter(i->Objects.equals(i.getRepairOrderId(),r.getId())).findFirst().orElseThrow();as("STAFF");inspections.decide(next.getId(),pass());rooms.setRoomAvailable(room1);assertEquals(1,jdbc.queryForObject("SELECT status FROM room WHERE id=?",Integer.class,room1));}
 @Test void managerCanForceCompleteWithoutClaim(){var r=open();as("OWNER");assertEquals(2,repairs.complete(r.getId(),null,true).getStatus());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM housekeeping_inspection WHERE repair_order_id=?",Integer.class,r.getId()));}
 @Test void managerCancelTerminatesTaskAndRequiresReinspection(){var r=open();as("MANAGER");assertEquals(3,repairs.cancel(r.getId(),"Professional repair unnecessary").getStatus());assertEquals(3,jdbc.queryForObject("SELECT status FROM hotel_task WHERE id=?",Integer.class,r.getTaskId()));assertEquals(3,jdbc.queryForObject("SELECT status FROM room WHERE id=?",Integer.class,room1));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM housekeeping_inspection WHERE repair_order_id=? AND status=0",Integer.class,r.getId()));}
 @Test void staffCannotCancelOrForceComplete(){var r=open();as("STAFF");assertThrows(AccessDeniedException.class,()->repairs.cancel(r.getId(),null));assertThrows(AccessDeniedException.class,()->repairs.complete(r.getId(),null,true));}
 @Test void financeReadsCostButCannotOperate(){var r=open();as("FINANCE");assertEquals(r.getId(),repairs.get(r.getId()).getId());assertFalse(repairs.list(room1,null,null,1,20).getItems().isEmpty());assertThrows(AccessDeniedException.class,()->repairs.complete(r.getId(),null,false));assertThrows(AccessDeniedException.class,()->repairs.cancel(r.getId(),null));}
 @ParameterizedTest@ValueSource(strings={"CUSTOMER","HR_ADMIN"})void customerAndHrDenied(String role)throws Exception{var r=open();as(role);assertThrows(AccessDeniedException.class,()->repairs.get(r.getId()));mvc.perform(get("/api/repair-orders").with(authentication(auth(role)))).andExpect(status().isForbidden());}
 @Test void anonymousIs401()throws Exception{mvc.perform(get("/api/repair-orders").with(anonymous())).andExpect(status().isUnauthorized());}
 @Test void actualCostNeverCreatesFolioItem(){var r=open();int before=jdbc.queryForObject("SELECT COUNT(*) FROM folio_item",Integer.class);claimAck(r);repairs.complete(r.getId(),RepairRequests.Complete.builder().actualCost(new BigDecimal("999.00")).build(),false);assertEquals(before,jdbc.queryForObject("SELECT COUNT(*) FROM folio_item",Integer.class));}
 @Test void damageAssessmentKeepsRepairSourceAndIndependentCharge(){var r=open();long stay=jdbc.queryForObject("SELECT stay_id FROM housekeeping_inspection WHERE id=?",Long.class,r.getInspectionId());long assignment=jdbc.queryForObject("SELECT assignment_id FROM housekeeping_inspection WHERE id=?",Long.class,r.getInspectionId());as("STAFF");var a=damage.report(DamageRequests.Report.builder().stayId(stay).assignmentId(assignment).sourceType(DamageSourceType.ROOM_REPAIR).sourceId(r.getId()).description("Structural damage responsibility review").requestKey("repair-damage-"+UUID.randomUUID()).build());as("FINANCE");var done=damage.assess(a.getId(),DamageRequests.Assess.builder().responsibility(DamageResponsibility.CUSTOMER).chargeAmount(new BigDecimal("120.00")).reason("Guest caused structural damage").build());assertEquals(r.getId(),done.getSourceId());assertEquals(2,done.getStatus());assertNull(done.getFolioItemId());}
 @Test void completionFailureRollsBackEverything(){var r=open();claimAck(r);String old=Thread.currentThread().getName();Thread.currentThread().setName("repair-fail");gate.arm("repair-fail","InspectionMapper.insertForRepair",true);try{assertThrows(RuntimeException.class,()->repairs.complete(r.getId(),null,false));}finally{gate.clear();Thread.currentThread().setName(old);}assertEquals(1,repairs.get(r.getId()).getStatus());assertEquals(1,jdbc.queryForObject("SELECT status FROM hotel_task WHERE id=?",Integer.class,r.getTaskId()));assertEquals(1,todos.get(todo(r.getTaskId())).getStatus());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM housekeeping_inspection WHERE repair_order_id=?",Integer.class,r.getId()));}
 @Test void concurrentCompletionIsIdempotent(){var r=open();claimAck(r);var pool=Executors.newFixedThreadPool(2);try{java.util.function.Supplier<Throwable> call=()->{as("STAFF");try{repairs.complete(r.getId(),null,false);return null;}catch(Throwable e){return e;}finally{org.springframework.security.core.context.SecurityContextHolder.clearContext();}};var a=pool.submit(call::get);var b=pool.submit(call::get);assertNull(result(a));assertNull(result(b));as("MANAGER");assertEquals(2,repairs.get(r.getId()).getStatus());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM housekeeping_inspection WHERE repair_order_id=?",Integer.class,r.getId()));}finally{pool.shutdownNow();}}
}
